import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkFirst, StaleWhileRevalidate, CacheFirst } from 'workbox-strategies';

cleanupOutdatedCaches();

// Precache assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Cache HTML pages (Inertia app shell) dengan NetworkFirst
registerRoute(
  ({ request }) => request.destination === 'document' || request.mode === 'navigate',
  new NetworkFirst({
    cacheName: 'sipreline-pages-cache',
    networkTimeoutSeconds: 3,
  })
);

// Cache fonts and static images
registerRoute(
  ({ request }) => request.destination === 'image' || request.destination === 'font',
  new CacheFirst({
    cacheName: 'sipreline-static-assets',
  })
);

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});
